<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\User\Infrastructure\Driven;

use Override;
use Throwable;
use DateInterval;
use DateTimeImmutable;
use Civi\Lughauth\Shared\Security\PasswordHasher;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Access\User\Domain\User;
use Civi\Lughauth\Features\Access\User\Domain\ValueObject\UserPasswordVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven\TrustedClientFinder;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipFilter;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentFilter;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\Role\Domain\Gateway\RoleQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\Gateway\RelyingPartyQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserCommandRepositoryGateway;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\Gateway\UserAcceptedTermsOfUseQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\TenantTermsOfUse;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\LoginGateway;
use Civi\Lughauth\Features\OAuth\Common\Infrastructure\Driven\UserLoaderAdapter;
use Civi\Lughauth\Features\OAuth\Consent\Application\Usecase\ScopesConsentUsecase;

class LoginAdapter implements LoginGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly PasswordHasher $hasher,
        private readonly UserLoaderAdapter $users,
        private readonly TenantConfigQueryRepositoryGateway $configs,
        private readonly UserAcceptedTermsOfUseQueryRepositoryGateway $userTerms,
        private readonly UserGroupMembershipQueryRepositoryGateway $userGroupMemberships,
        private readonly UserRoleAssignmentQueryRepositoryGateway $userRoleAssignments,
        private readonly TrustedClientFinder $clients,
        private readonly RelyingPartyQueryRepositoryGateway $parties,
        private readonly UserCommandRepositoryGateway $writeUsers,
        private readonly RoleQueryRepositoryGateway $roles,
        private readonly ScopesConsentUsecase $scopesConsent,
    ) {
    }

    #[Override]
    public function fillPreLoadById(
        string $tenant,
        AuthenticationRequest $client,
        ChallengesState $challenges
    ): AuthenticationResult {
        $username = $challenges->username ?? '';
        $this->logDebug('OIDC login fill-pre-load-by-id', ['tenant' => $tenant, 'username' => $username]);
        $span = $this->startSpan('oidc.login.fill_pre_load_by_id', ['tenant' => $tenant]);
        try {
            $theTenant = $this->users->checkTenant($tenant, $username);
            $theUser = $this->users->checkUserSubjet($theTenant, $username);
            if ($terms = $this->checkTerms($theTenant, $theUser, $client->audiences)) {
                $this->logInfo('OIDC login requires terms acceptance', ['tenant' => $tenant, 'username' => $username]);
                return $terms;
            }
            if ($scopes = $this->checkScopesConsent($theTenant, $theUser, $client)) {
                $this->logInfo('OIDC login requires scopes consent', ['tenant' => $tenant, 'username' => $username]);
                return $scopes;
            }
            $root = $theTenant->isRoot();
            return new AuthenticationResult(
                valid: true,
                id: $theUser->uid(),
                name: $theUser->getName(),
                email: $theUser->getEmail(),
                tenant: $theTenant->uid(),
                tenantName: $theTenant->getName(),
                scope: $this->loadScopes($theTenant, $client->scope),
                audiences: $client->audiences,
                roles: $this->loadRoles($client, $theUser),
                groups: $this->loadGroups($client, $theUser),
                tenancyMode: $root ? 'global' : 'tenant',
            );
        } catch (Throwable $ex) {
            $span->recordException($ex);
            $this->logWarning('OIDC login fill-pre-load-by-id error', ['tenant' => $tenant, 'username' => $username, 'error' => $ex instanceof LoginException ? ($ex->auth->error ?? '') : $ex->getMessage()]);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    #[Override]
    public function fillPreAuthenticated(
        string $tenant,
        AuthenticationRequest $client,
        ChallengesState $challenges
    ): AuthenticationResult {
        $username = $challenges->username ?? '';
        $this->logDebug('OIDC login fill-pre-authenticated', ['tenant' => $tenant, 'username' => $username]);
        $span = $this->startSpan('oidc.login.fill_pre_authenticated', ['tenant' => $tenant]);
        try {
            $theTenant = $this->users->checkTenant($tenant, $username);
            $theUser = $this->users->checkUserOrSubject($theTenant, $username);
            if ($terms = $this->checkTerms($theTenant, $theUser, $client->audiences)) {
                $this->logInfo('OIDC login requires terms acceptance', ['tenant' => $tenant, 'username' => $username]);
                return $terms;
            }
            if ($scopes = $this->checkScopesConsent($theTenant, $theUser, $client)) {
                $this->logInfo('OIDC login requires scopes consent', ['tenant' => $tenant, 'username' => $username]);
                return $scopes;
            }
            $root = $theTenant->isRoot();
            return new AuthenticationResult(
                valid: true,
                id: $theUser->uid(),
                name: $theUser->getName(),
                email: $theUser->getEmail(),
                tenant: $theTenant->uid(),
                tenantName: $theTenant->getName(),
                scope: $this->loadScopes($theTenant, $client->scope),
                audiences: $client->audiences,
                roles: $this->loadRoles($client, $theUser),
                groups: $this->loadGroups($client, $theUser),
                tenancyMode: $root ? 'global' : 'tenant',
            );
        } catch (Throwable $ex) {
            $span->recordException($ex);
            $this->logWarning('OIDC login fill-pre-authenticated error', ['tenant' => $tenant, 'username' => $username, 'error' => $ex instanceof LoginException ? ($ex->auth->error ?? '') : $ex->getMessage()]);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    #[Override]
    public function validatedUserData(
        string $tenant,
        string $username,
        string $password,
        AuthenticationRequest $client
    ): AuthenticationResult {
        $this->logDebug('OIDC login validate-credentials start', ['tenant' => $tenant, 'username' => $username]);
        $span = $this->startSpan('oidc.login.validate_credentials', ['tenant' => $tenant]);
        try {
            $theTenant = $this->users->checkTenant($tenant, $username);
            $theUser = $this->users->checkUser($theTenant, $username);
            $theUser = $this->checkPassword($theTenant, $theUser, $password);
            if ($temp = $this->checkTemporalPassword($theTenant, $theUser)) {
                $this->logInfo('OIDC login requires password change', ['tenant' => $tenant, 'username' => $username]);
                return $temp;
            }
            if ($reqMfa = $this->checkMfaConfigurationRequired($theTenant, $theUser)) {
                $this->logInfo('OIDC login requires MFA setup', ['tenant' => $tenant, 'username' => $username]);
                return $reqMfa;
            }
            if ($mfa = $this->checkMfa($theTenant, $theUser)) {
                $this->logInfo('OIDC login requires MFA verification', ['tenant' => $tenant, 'username' => $username]);
                return $mfa;
            }
            if ($terms = $this->checkTerms($theTenant, $theUser, $client->audiences)) {
                $this->logInfo('OIDC login requires terms acceptance', ['tenant' => $tenant, 'username' => $username]);
                return $terms;
            }
            if ($scopes = $this->checkScopesConsent($theTenant, $theUser, $client)) {
                $this->logInfo('OIDC login requires scopes consent', ['tenant' => $tenant, 'username' => $username]);
                return $scopes;
            }
            $root = $theTenant->isRoot();
            $this->markLoginOk($theUser);
            $this->logInfo('OIDC login credentials validated ok', ['tenant' => $tenant, 'username' => $username]);
            return new AuthenticationResult(
                valid: true,
                id: $theUser->uid(),
                name: $theUser->getName(),
                email: $theUser->getEmail(),
                tenant: $theTenant->uid(),
                tenantName: $theTenant->getName(),
                scope: $this->loadScopes($theTenant, $client->scope),
                audiences: $client->audiences,
                roles: $this->loadRoles($client, $theUser),
                groups: $this->loadGroups($client, $theUser),
                tenancyMode: $root ? 'global' : 'tenant',
            );
        } catch (Throwable $ex) {
            $span->recordException($ex);
            $this->logWarning('OIDC login validate-credentials error', ['tenant' => $tenant, 'username' => $username, 'error' => $ex instanceof LoginException ? ($ex->auth->error ?? '') : $ex->getMessage()]);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Verifies the password in constant time and, when the stored hash was built with old options,
     * replaces it with a fresh one (the plain password is only known at this point).
     */
    private function checkPassword(Tenant $tenant, User $user, string $password): User
    {
        if (!$user->verifyPassword($this->hasher, $password)) {
            $this->markLoginFail($user);
            throw new LoginException(auth: AuthenticationResult::wrongCredentials($tenant->getName(), $user->getName()));
        }
        return $this->rehashPasswordIfNeeded($tenant, $user, $password);
    }

    private function rehashPasswordIfNeeded(Tenant $tenant, User $user, string $password): User
    {
        if (!$user->passwordNeedsRehash($this->hasher)) {
            return $user;
        }
        try {
            // withPassword does not record a change password event: the password is the same
            return $this->writeUsers->update($user, $user->withPassword(UserPasswordVO::fromPlainText($this->hasher, $password)));
        } catch (Throwable $ex) {
            // A failed rehash must not block the login: it will be retried on the next one
            $this->logWarning('OIDC login password rehash error', ['tenant' => $tenant->getName(), 'username' => $user->getName(), 'error' => $ex->getMessage()]);
            return $user;
        }
    }

    private function checkTemporalPassword(Tenant $tenant, User $user): ?AuthenticationResult
    {
        return $user->isTemporalPassword() ? AuthenticationResult::newPasswordRequired() : null;
    }

    private function checkTerms(Tenant $tenant, User $user, array $audiences): ?AuthenticationResult
    {
        $terms = $this->users->loadTenantTerms($tenant, $audiences);
        foreach ($terms as $term) {
            if (!$term instanceof TenantTermsOfUse) {
                continue;
            }
            $accepted = $this->userTerms->findOneByUserAndConditions($user, $term);
            if (!$accepted) {
                return AuthenticationResult::consentRequired();
            }
        }
        return null;
    }

    private function checkScopesConsent(Tenant $tenant, User $user, AuthenticationRequest $client): ?AuthenticationResult
    {
        $pending = $this->scopesConsent->pendingScopes(
            $tenant->getName(),
            $user->getName(),
            $client->client->id,
            $client->scope
        );
        return $pending ? AuthenticationResult::scopesConsentRequired() : null;
    }

    private function checkMfaConfigurationRequired(Tenant $tenant, User $user): ?AuthenticationResult
    {
        if ($user->getSecondFactorSeed() !== null && $user->getSecondFactorSeed() !== '') {
            return null;
        }
        if ($user->isUseSecondFactors()) {
            return AuthenticationResult::newMfaRequired();
        }
        $conf = $this->configs->findOneByTenant($tenant);
        return ($conf && $conf->isForceMfa()) ? AuthenticationResult::newMfaRequired() : null;
    }

    private function checkMfa(Tenant $tenant, User $user): ?AuthenticationResult
    {
        $seed = $user->getSecondFactorSeed();
        return ($seed !== null && $seed !== '' && $user->isUseSecondFactors())
            ? AuthenticationResult::mfaRequired()
            : null;
    }

    private function markLoginFail(User $user): void
    {
        $this->markLogin($user, true);
    }

    private function markLoginOk(User $user): void
    {
        $this->markLogin($user, false);
    }

    private function markLogin(User $user, bool $fail): void
    {
        $limit = 3;
        $code = $this->users->userCodeForUpdate($user);
        if ($fail) {
            if ($code->getFailedLoginAttempts() >= $limit) {
                $this->writeUsers->update($user, $user->block((new DateTimeImmutable())->add(new DateInterval("PT6H"))));
                $this->users->updateCode($code->markLoginBlock());
            } else {
                $this->users->updateCode($code->markLoginFail());
            }
        } else {
            $this->users->updateCode($code->markLoginOk());
        }
    }

    private function loadScopes(Tenant $tenant, string $scope): string
    {
        $scopes = array_diff(explode(' ', $scope), ['platform:global_access']);
        return implode(' ', $tenant->isRoot() ? ['platform:global_access', ...$scopes] : $scopes);
    }

    /**
     * @return array<array-key, list<string>>
     */
    private function loadRoles(AuthenticationRequest $client, User $user): array
    {
        /** @var array<array-key, list<string>> $roles */
        $roles = [];
        // Tengo roles para cualquier audiencia
        /** @var list<string> $forAll */
        $forAll = [];
        $this->rolesFromAssignment(new UserRoleAssignmentFilter(user: $user)->withForAllAudiences(true), $forAll);
        if ($client->audiences) {
            foreach ($client->audiences as $audience) {
                if (!is_string($audience)) {
                    continue;
                }
                $roles[$audience] = $forAll;
                if ($from = $this->clients->findForTenant($user->getTenant(), $audience)) {
                    $this->rolesFromAssignment(new UserRoleAssignmentFilter(
                        user: $user,
                        trustedClient: $from
                    ), $roles[$audience]);
                }
                if ($from = $this->parties->findOneByCode($audience)) {
                    $this->rolesFromAssignment(new UserRoleAssignmentFilter(
                        user: $user,
                        relyingParty: $from
                    ), $roles[$audience]);
                }
            }
        }
        return $roles;
    }

    /**
     * @param list<string> $roles
     * @psalm-param-out list<string> $roles
     */
    private function rolesFromAssignment(UserRoleAssignmentFilter $filter, array &$roles): void
    {
        $assignments = $this->userRoleAssignments->list($filter);
        foreach ($assignments->values() as $assignment) {
            $assignmentRoles = $assignment->getRoles();
            if (null === $assignmentRoles) {
                continue;
            }
            foreach ($assignmentRoles as $role) {
                if ($role === null) {
                    continue;
                }
                $ref = $role->getRole();
                if ($ref === null) {
                    continue;
                }
                $theRole = $this->roles->resolve($ref);
                if ($theRole) {
                    $roleName = $theRole->getName();
                    if ($roleName !== null && $roleName !== '' && !in_array($roleName, $roles, true)) {
                        $roles[] = $roleName;
                    }
                }
            }
        }
    }

    /**
     * @psalm-return array<never, never>
     */
    private function loadGroups(AuthenticationRequest $client, User $user): array
    {
        /** @var list<string> $groups */
        $groups = [];
        /** @var list<string> $forAll */
        $forAll = [];
        $this->groupsFromMembership(new UserGroupMembershipFilter(user: $user)->withForAllAudiences(true), $forAll);
        if ($client->audiences) {
            foreach ($client->audiences as $audience) {
                if (!is_string($audience)) {
                    continue;
                }
                $audienceGroups = $forAll;
                if ($from = $this->clients->findForTenant($user->getTenant(), $audience)) {
                    $this->groupsFromMembership(new UserGroupMembershipFilter(
                        user: $user,
                        trustedClient: $from
                    ), $audienceGroups);
                }
                if ($from = $this->parties->findOneByCode($audience)) {
                    $this->groupsFromMembership(new UserGroupMembershipFilter(
                        user: $user,
                        relyingParty: $from
                    ), $audienceGroups);
                }
                foreach ($audienceGroups as $group) {
                    if (!in_array($group, $groups, true)) {
                        $groups[] = $group;
                    }
                }
            }
            return $groups;
        }
        return $forAll;
    }

    /**
     * @param list<string> $groups
     * @psalm-param-out list<string> $groups
     */
    private function groupsFromMembership(UserGroupMembershipFilter $filter, array &$groups): void
    {
        $memberships = $this->userGroupMemberships->list($filter);
        foreach ($memberships->values() as $membership) {
            $rawGroups = $membership->getGroups();
            foreach ($this->parseGroupList($rawGroups) as $group) {
                if (!in_array($group, $groups, true)) {
                    $groups[] = $group;
                }
            }
        }
    }

    /**
     * @psalm-return list<string>
     */
    private function parseGroupList(?string $groups): array
    {
        if ($groups === null || $groups === '') {
            return [];
        }
        $parts = array_map('trim', explode(',', $groups));
        $parts = array_filter($parts, static fn (string $value): bool => $value !== '');
        return array_values($parts);
    }
}
